#include <vector>
#include <algorithm>

class Solution {
public:
    int minStartValue(std::vector<int>& nums) {
        int cur = 0, minPrefix = 0;
        for (int x : nums) {
            cur += x;
            minPrefix = std::min(minPrefix, cur);
        }
        return 1 - minPrefix;
    }
};

class Solution {
    public int minStartValue(int[] nums) {
        int cur = 0, minPrefix = 0;
        for (int x : nums) {
            cur += x;
            minPrefix = Math.min(minPrefix, cur);
        }
        return 1 - minPrefix;
    }
}

var minStartValue = function(nums) {
    let cur = 0, minPrefix = 0;
    for (const x of nums) {
        cur += x;
        minPrefix = Math.min(minPrefix, cur);
    }
    return 1 - minPrefix;
};
